window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-53523bc3e32e4f5e"]={"versions": [{"id": "FIG-53523bc3e32e4f5e", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Adc_Init()</code>) zur Initialisierungsphase des ADC-Treibers in der AUTOSAR-Basissoftware. Das Diagramm modelliert die Interaktion zwischen dem ECU State Manager (EcuM) als Aufrufer auf der System-/Service-Ebene und dem ADC-Treiber (Adc) im Microcontroller Abstraction Layer (MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>EcuM::EcuM</code>: Lebenslinie des ECU State Managers als steuernde Instanz der Initialisierungssequenz.</li>\n<li><code>Adc::Adc</code>: Lebenslinie des ADC-Treibermoduls als ausführende Instanz.</li>\n<li><code>Adc_Init(ConfigPtr)</code>: Synchroner Funktionsaufruf / synchrone Botschaft mit dem Parameter <code>ConfigPtr</code>.</li>\n<li><code>Adc_Init</code>: Rückkehrnachricht (gestrichelte Linie) vom ADC-Treiber an den EcuM.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die aktive Phase des EcuM stößt über einen synchronen Funktionsaufruf <code>Adc_Init(ConfigPtr)</code> die Initialisierung des ADC-Treibers an.</li>\n<li>Während der Abarbeitung von <code>Adc_Init</code> übernimmt der ADC-Treiber die Ausführung (Aktivierungsbalken auf der Lebenslinie <code>Adc::Adc</code>).</li>\n<li>Nach Abschluss der Initialisierung von Hardware und Treiberstrukturen kehrt der Kontrollfluss über die Rückkehrnachricht <code>Adc_Init</code> zum EcuM zurück, der die Ausführung fortsetzt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Aufruf <code>Adc_Init(ConfigPtr)</code> ist die zentrale Initialisierungsschnittstelle des ADC-Treibers. Der Aufruf muss synchron durch den EcuM erfolgen, bevor andere ADC-Treiber-APIs aufgerufen werden dürfen. Dem Aufruf ist ein zeigerbasierter Konfigurationssatz (<code>ConfigPtr</code>) zu übergeben.</p>"}, {"id": "FIG-1a3a602dcd465126", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Adc_Init()</code>) zur Initialisierungsphase des ADC-Treibers in der AUTOSAR-Basissoftware. Das Diagramm modelliert die Interaktion zwischen dem ECU State Manager (EcuM) auf Service-Ebene und dem ADC-Treiber (Adc) im MCAL, ergänzt um ein UML-Notizfeld zur Spezifikationsdokumentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM::EcuM</code>: Lebenslinie des ECU State Managers, typisiert als BSW-Modul.</li>\n<li><code>«module» Adc::Adc</code>: Lebenslinie des ADC-Treibers, typisiert als BSW-Modul.</li>\n<li><code>Adc_Init(ConfigPtr)</code>: Synchroner Funktionsaufruf mit dem Übergabeparameter <code>ConfigPtr</code>.</li>\n<li><code>Adc_Init</code>: Rückkehrnachricht der Initialisierungsfunktion an den EcuM.</li>\n<li>Notizfeld: Dokumentationsblock mit Statusangabe (<code>Status: proposed by TO as per SWS Adc 2.0.1</code>), Kurzbeschreibung (<code>Description: ADC hardware and driver initialization</code>) und Feld <code>Comments:</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die aktive Phase des EcuM stößt über einen synchronen Funktionsaufruf <code>Adc_Init(ConfigPtr)</code> die Initialisierung des ADC-Treibers an.</li>\n<li>Während der Abarbeitung von <code>Adc_Init</code> übernimmt der ADC-Treiber die Ausführung (Aktivierungsbalken auf der Lebenslinie <code>Adc::Adc</code>).</li>\n<li>Nach Abschluss der Initialisierung von Hardware und Treiberstrukturen kehrt der Kontrollfluss über die Rückkehrnachricht <code>Adc_Init</code> zum EcuM zurück, der die Ausführung fortsetzt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Aufruf <code>Adc_Init(ConfigPtr)</code> ist die zentrale Initialisierungsschnittstelle des ADC-Treibers. Der Aufruf muss synchron durch den EcuM erfolgen, bevor andere ADC-Treiber-APIs aufgerufen werden dürfen. Dem Aufruf ist ein zeigerbasierter Konfigurationssatz (<code>ConfigPtr</code>) zu übergeben.</p>"}, {"id": "FIG-5037badb2bd9171e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Adc_Init()</code>) zur Initialisierungsphase des ADC-Treibers in der AUTOSAR-Basissoftware. Das Diagramm modelliert die Interaktion zwischen dem ECU State Manager (EcuM) auf Service-Ebene und dem ADC-Treiber (Adc) im MCAL, ergänzt um ein UML-Notizfeld zur Spezifikationsdokumentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>«module» EcuM</code>: Lebenslinie des ECU State Managers als BSW-Modul.</li>\n<li><code>«module» Adc</code>: Lebenslinie des ADC-Treibers als BSW-Modul.</li>\n<li><code>Adc_Init(const Adc_ConfigType<em>)</code>: Synchroner Funktionsaufruf mit explizitem Typhinweis <code>const Adc_ConfigType</em></code> für den Konfigurationszeiger.</li>\n<li><code>Adc_Init()</code>: Rückkehrnachricht des Initialisierungsaufrufs an den EcuM.</li>\n<li>Notizfeld: Dokumentationsblock (<code>Status: proposed by TO as per SWS Adc 2.0.1</code>, <code>Description: ADC hardware and driver initialization</code>, <code>Comments:</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der EcuM initiiert synchron den Initialisierungsaufruf <code>Adc_Init(const Adc_ConfigType*)</code> an den ADC-Treiber.</li>\n<li>Der ADC-Treiber führt die Hardware- und Treiberinitialisierung auf Basis des übergebenen Konfigurationszeigers aus (Aktivierungsbalken auf der Lebenslinie <code>Adc</code>).</li>\n<li>Nach Beendigung der Initialisierungsroutine erfolgt die Rückkehr via <code>Adc_Init()</code> an den aufrufenden EcuM.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstelle <code>Adc_Init(const Adc_ConfigType*)</code> erfordert normativ die Übergabe eines typisierten Zeigers auf eine konstante Konfigurationsstruktur vom Typ <code>Adc_ConfigType</code>. Der Aufruf ist synchron und bildet die zwingende Voraussetzung für alle weiteren Treiberoperationen.</p>"}], "trans": [{"from": "FIG-53523bc3e32e4f5e", "to": "FIG-1a3a602dcd465126", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Lebenslinien-Köpfe: Stereotyp <code>«module»</code> über den Bezeichnern ergänzt.</li>\n<li>Kommentarfeld (UML-Note): Metadatenblock mit <code>Status: proposed by TO as per SWS Adc 2.0.1</code>, <code>Description: ADC hardware and driver initialization</code> und <code>Comments:</code> im unteren Diagrammbereich ergänzt.</li>\n</ul>"}, {"from": "FIG-1a3a602dcd465126", "to": "FIG-5037badb2bd9171e", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Aufrufsignatur: Parameter von <code>Adc_Init(ConfigPtr)</code> zu <code>Adc_Init(const Adc_ConfigType*)</code> typisiert.</li>\n<li>Rückkehrnachricht: Bezeichnung von <code>Adc_Init</code> zu <code>Adc_Init()</code> geändert.</li>\n<li>Lebenslinien-Bezeichner: Qualifizierte Namen <code>EcuM::EcuM</code> und <code>Adc::Adc</code> zu <code>EcuM</code> bzw. <code>Adc</code> vereinfacht.</li>\n</ul>"}]};
